import {createPlaceholderRotation} from './copy.js';
import {today,addDays,dayNumber,fromDay,daysBetween,fmt,roundUp,stats,dates,scheduled,trainingDays,weekday,validateChallenge,parseBackup,chartPoints,catchup,suggestedDeadline,repeatChallenge,allocate,weeklyReview,monthEnd,challengeLink,linkKinds} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nextChallengePlaceholder=createPlaceholderRotation();
let reviewPeriod='current';
const uid=()=>crypto.randomUUID(),key='stride-v1',weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
let challenges=[],view='today',filter='active',selected=null,revision=0,modalRevision=0,loadError=false;
let displayedDay=today(),displayedOffset=new Date().getTimezoneOffset(),dayTimer;
const main=$('#main'),modal=$('#modal');
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short'});
const dateRange=c=>`${dateLabel(c.start)} — ${dateLabel(c.end)} ${c.end.slice(0,4)}`;
const run=c=>/km|mile|run|walk/i.test(c.unit+' '+c.name),quick=c=>c.quickAdd||(run(c)?1:25);
const scheduleLabel=c=>c.mode==='total'?`${trainingDays(c).length===7?'Every day':trainingDays(c).map(d=>weekdays[d]).join(', ')} · flexible total`:(c.schedule?.weekly||7)<trainingDays(c).length?`${c.schedule.weekly} sessions / week · ${fmt(c.goal)} ${esc(c.unit)} each`:`${fmt(c.goal)} ${esc(c.unit)} · ${trainingDays(c).length===7?'every day':trainingDays(c).map(d=>weekdays[d]).join(', ')}`;
function nativeRead(){if(!window.StrideAndroid?.getData)return false;const raw=window.StrideAndroid.getData();if(!raw)return false;const parsed=JSON.parse(raw);challenges=parseBackup(raw);revision=parsed.revision||0;return true;}
try{if(!nativeRead()){const raw=localStorage.getItem(key);if(raw)challenges=parseBackup(raw);}}catch(e){loadError=true;}
function persist(next=challenges){try{next.forEach(validateChallenge);if(window.StrideAndroid?.saveData){if(modal.open&&modalRevision!==revision){close();render();toast('A widget updated your progress. Reopen this action to use the latest data.');return false;}const newRevision=window.StrideAndroid.saveData(JSON.stringify({version:2,challenges:next}),revision);if(newRevision<0){nativeRead();close();render();toast('Progress changed elsewhere. Please try that action again.');return false;}revision=newRevision;}else localStorage.setItem(key,JSON.stringify({version:2,challenges:next}));challenges=next;return true;}catch(e){toast('Could not save: '+e.message);return false;}}
function scheduleDayRefresh(){clearTimeout(dayTimer);const midnight=new Date();midnight.setHours(24,0,0,100);dayTimer=setTimeout(()=>refreshCurrentDay(),Math.max(100,midnight.getTime()-Date.now()));}
function refreshDayDrafts(){
 const form=$('#log-form');if(form){const c=challenges.find(c=>c.id===form.dataset.challengeId);if(c){const date=$('#date'),max=c.end<today()?c.end:today();date.max=max;if(form.dataset.followsToday==='true'&&max>=c.start)date.value=max;}}
 const challengeForm=$('#challenge-form');if(challengeForm)challengeForm.dispatchEvent(new Event('change'));
 const planDate=$('#plan-end');if(planDate){planDate.min=today();planDate.dispatchEvent(new Event('input'));}
}
function refreshCurrentDay({force=false,readNative=false}={}){
 const day=today(),offset=new Date().getTimezoneOffset(),changed=day!==displayedDay||offset!==displayedOffset;
 if(readNative&&window.StrideAndroid?.getData){try{nativeRead();}catch(e){toast('Could not load device data.');}}
 if(changed||force){displayedDay=day;displayedOffset=offset;render();if(changed)refreshDayDrafts();}
 scheduleDayRefresh();
}
window.refreshNative=()=>refreshCurrentDay({force:true,readNative:true});
window.onAppResume=window.refreshNative;
if(!loadError&&window.StrideAndroid?.saveData&&!window.StrideAndroid.getData())persist();
let toastTimer;function toast(message,undo=null){let box=$('#toast');clearTimeout(toastTimer);if(modal.open){$('#toast').classList.remove('visible');box=$('#dialog-status');if(!box){box=document.createElement('div');box.id='dialog-status';box.className='dialog-status';box.setAttribute('role','status');$('#modal-content').append(box);}}box.replaceChildren();const label=document.createElement('span');label.textContent=message;box.append(label);if(undo){const b=document.createElement('button');b.textContent='Undo';b.onclick=()=>{clearTimeout(toastTimer);undo();};box.append(b);}if(modal.open){box.scrollIntoView({block:'nearest'});return;}box.classList.add('visible');toastTimer=setTimeout(()=>box.classList.remove('visible'),undo?10000:4000);}
function open(content){modalRevision=revision;$('#modal-content').innerHTML=content;if(!modal.open)modal.showModal();}
function close(){modal.close();}
function title(text){return `<div class="modal-heading"><h2>${text}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div>`;}
const logs=()=>challenges.flatMap(c=>c.logs.map(l=>({...l,challenge:c}))).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));
function go(next){view=next;selected=null;render();window.scrollTo(0,0);}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===view);b.setAttribute('aria-current',b.dataset.nav===view?'page':'false');});if(selected)return detail();if(view==='today')return renderToday();if(view==='activity')return activity();if(view==='insights')return insights();renderChallenges();}
function heading(kicker,heading,sub,action=true){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${heading}</h1><p>${sub}</p></div>${action?'<button class="primary" data-action="new">＋ New challenge</button>':''}</div>`;}
function empty(){return `<section class="empty"><span class="empty-mark">Z</span><h2>Give your effort a direction.</h2><p>A clear goal. A date to aim for.<br>One small action at a time.</p><button class="primary" data-action="new">Create a challenge</button><div class="quick"><button data-template="pushups">3,000 pushups</button><button data-template="run">3 km a day</button></div></section>`;}
function renderToday(){const active=challenges.filter(c=>c.start<=today()&&c.end>=today());const due=active.filter(c=>stats(c).due>0),done=active.filter(c=>stats(c).scheduledToday&&stats(c).due<=0);const total=active.filter(c=>stats(c).scheduledToday).length;const percentage=total?Math.round(done.length/total*100):0;
 main.innerHTML=heading(new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'}),'Make today<br><em>count.</em>','Your challenge. Your deadline. Your next move.')+`<div class="today-layout"><section class="mission-hero"><div class="eyebrow">TODAY’S PULSE <span class="live-dot"></span></div><div class="orbit" style="--progress:${percentage}%"><div><strong>${due.length.toString().padStart(2,'0')}</strong><span>missions remaining</span></div></div><div class="hero-foot"><span>${done.length} of ${total} scheduled goals met</span><b>${percentage}%</b></div><div class="route-line"><i style="width:${percentage}%"></i></div><p>${!total?'Rest is part of the plan.':due.length?'One focused effort moves the line.':'Today’s work is done. Enjoy the breathing room.'}</p><span class="orbit-decoration" aria-hidden="true">✦</span></section><section class="today-list"><div class="section-heading"><h2>Your next moves <span>${due.length}</span></h2><button class="text-button" data-nav="challenges">See all ↗</button></div>${!challenges.length?empty():due.length?due.map(todayCard).join(''):`<section class="quiet-card"><span class="status-dot"></span><h3>${total?'You’ve earned the pause.':'No work scheduled today.'}</h3><p>${total?'All today’s targets are met.':'Your challenges are ready when your next session comes around.'}</p><button class="secondary" data-nav="challenges">View challenges</button></section>`}${done.length?`<div class="section-heading small"><h3>Already in the bank</h3><span>${done.length} done</span></div>${done.map(c=>`<button class="done-row" data-detail="${esc(c.id)}"><span>✓</span>${esc(c.name)}<small>${fmt(stats(c).today)} ${esc(c.unit)}</small></button>`).join('')}`:''}</section></div><div class="brand-footer">Built for your next small win. <b>by ecletra</b></div>`;
}
function todayCard(c){const s=stats(c);return `<article class="mission-card"><div class="mission-top"><span class="category">${run(c)?'DISTANCE':'EFFORT'} / ${c.mode==='total'?'FLEXIBLE':'STRICT'}</span><span class="badge ${s.status==='Behind pace'?'behind':''}">${s.status}</span></div><button class="card-title" data-detail="${esc(c.id)}"><h3>${esc(c.name)}</h3></button><div class="today-amount"><strong>${fmt(roundUp(s.due))}</strong><span>${esc(c.unit)}<small>remaining today</small></span></div>${s.capacityShortfall>0&&c.capacity?`<p class="plan-warning">Your remaining work won’t fit these limits. <button class="text-button" data-plan="${esc(c.id)}">Adjust plan</button></p>`:''}<div class="mini-route"><span>${fmt(s.today)} logged today</span><span>by ${dateLabel(c.end)}</span></div><div class="track"><i style="width:${s.progress*100}%"></i></div><div class="mission-actions"><button class="primary" data-quick="${esc(c.id)}">＋ ${fmt(quick(c))} ${esc(c.unit)}</button><button class="secondary" data-log="${esc(c.id)}">Log progress</button>${c.mode==='total'?`<button class="icon-button" data-plan="${esc(c.id)}" aria-label="Adjust plan">↗</button>`:''}</div></article>`;}
function card(c){const s=stats(c),ended=c.end<today()&&!s.completed;return `<article class="card"><div class="card-top"><span class="category">${c.mode==='total'?'TOTAL GOAL':'SESSION GOAL'}</span><span class="badge ${s.status==='Behind pace'?'behind':''}">${s.status}</span></div><button class="card-title" data-detail="${esc(c.id)}"><h3>${esc(c.name)}</h3><p>${dateRange(c)}</p></button><div class="progress-number"><strong>${fmt(c.mode==='total'?s.total:s.hitDays)} <small>/ ${fmt(c.mode==='total'?s.target:s.required)} ${c.mode==='total'?esc(c.unit):'sessions'}</small></strong><span>${Math.floor(s.progress*100)}%</span></div><div class="track"><i style="width:${s.progress*100}%"></i></div><p class="schedule-caption">${scheduleLabel(c)}</p>${c.link?`<p class="linked-caption">↗ ${esc(c.link.label||linkKinds[c.link.kind])}</p>`:''}<div class="card-stats"><div><small>${ended?'Still remaining':c.mode==='total'?'Remaining today':'Missed sessions'}</small><b>${c.mode==='total'?fmt(ended?s.remaining:roundUp(s.due))+' '+esc(c.unit):ended?s.required-s.hitDays:s.missed}${c.mode==='daily'&&ended?' sessions':''}</b></div><div><small>${ended?'Deadline passed':'Scheduled days left'}</small><b>${ended?dateLabel(c.end):s.remainingDays}</b></div></div>${s.capacityShortfall>0&&c.capacity&&!ended?'<p class="plan-warning">Your remaining work no longer fits your limits. Adjust the plan.</p>':''}<div class="mission-actions"><button class="secondary" ${ended&&c.mode==='total'?`data-plan="${esc(c.id)}"`:`data-log="${esc(c.id)}"`}>${ended&&c.mode==='total'?'Extend deadline':'＋ Log progress'}</button><button class="text-button" data-repeat="${esc(c.id)}">Repeat ↗</button></div></article>`;}
function renderChallenges(){const shown=challenges.filter(c=>filter==='all'||filter==='active'&&c.end>=today()&&!stats(c).completed||filter==='finished'&&(c.end<today()||stats(c).completed));main.innerHTML=heading('THE BIGGER PICTURE','Choose your<br><em>next chapter.</em>','A place for the things you want to finish.')+`<div class="section-heading"><h2>Your challenges <span>${challenges.length}</span></h2><div class="tabs" role="group" aria-label="Filter challenges">${[['active','Active'],['finished','Finished'],['all','All']].map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'selected':''}">${label}</button>`).join('')}</div></div><div class="cards">${shown.map(card).join('')||(!challenges.length?empty():'<div class="empty"><h2>A little room for what’s next.</h2><p>Try another filter, or create a challenge.</p></div>')}</div>`;}
function challengeForm(id=null,template=null){
 const c=challenges.find(c=>c.id===id),now=today();
 const d=c||{name:template==='pushups'?'3,000 pushups':template==='run'?'3 km every day':'',goal:template==='pushups'?3000:template==='run'?3:'',unit:template==='run'?'km':template==='pushups'?'reps':'',mode:template==='run'?'daily':'total',start:now,end:monthEnd(now)};
 open(`${title(c?'Edit challenge':'Set your direction')}<form id="challenge-form"><label for="name">Challenge name</label><input id="name" name="name" maxlength="80" required placeholder="${esc(nextChallengePlaceholder())}" value="${esc(d.name)}"><label for="mode">What would you like to achieve?</label><select id="mode" name="mode"><option value="total" ${d.mode==='total'?'selected':''}>A total by a deadline</option><option value="daily" ${d.mode==='daily'?'selected':''}>A target each session</option></select><p class="help" id="mode-help">${d.mode==='daily'?'Each target day counts separately. Extra effort cannot replace a missed day.':'Log whenever you can. Zelo adjusts the remaining work across your scheduled days.'}</p><div class="row"><div><label for="goal">${d.mode==='daily'?'Target per session':'Total target'}</label><input id="goal" name="goal" type="number" min="0.01" step="any" max="1000000000" required value="${d.goal}"></div><div><label for="unit">Unit</label><input id="unit" name="unit" maxlength="20" required placeholder="reps, km, pages" value="${esc(d.unit)}"></div></div><div class="row"><div><label for="start">Start date</label><input id="start" name="start" type="date" required value="${d.start}"></div><div><label for="end">End date</label><input id="end" name="end" type="date" required value="${d.end}"></div></div>
 <details class="options-panel" id="schedule-options"><summary>Schedule & reminders <span>Optional</span></summary><fieldset><legend>Scheduled days</legend><div class="day-picker">${[1,2,3,4,5,6,0].map(n=>`<label><input type="checkbox" name="days" value="${n}" ${trainingDays(d).includes(n)?'checked':''}><span>${weekdays[n]}</span></label>`).join('')}</div></fieldset><div id="weekly-wrap" ${d.mode!=='daily'?'hidden':''}><label for="weekly">Sessions per week</label><select id="weekly" name="weekly">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${(d.schedule?.weekly||7)===n?'selected':''}>${n}</option>`).join('')}</select><p class="help">Meet your quota on any selected scheduled days. Weeks run Monday–Sunday; partial weeks need only the available days.</p></div><div id="capacity-wrap" ${d.mode!=='total'?'hidden':''}><label class="check-label"><input id="capacity-enabled" name="capacity" type="checkbox" ${d.capacity?'checked':''}> Limit how much I plan for a day</label><div id="capacity-fields" ${!d.capacity?'hidden':''}><div class="row"><div><label for="weekday-limit">Weekday maximum</label><input id="weekday-limit" name="weekdayLimit" type="number" min="0.01" max="1000000000" step="any" value="${d.capacity?.weekday||100}"></div><div><label for="weekend-limit">Weekend maximum</label><input id="weekend-limit" name="weekendLimit" type="number" min="0.01" max="1000000000" step="any" value="${d.capacity?.weekend||200}"></div></div><p class="help">In your chosen unit. These cap your planned targets, not what you’re allowed to log. Rest days are excluded.</p></div></div><label for="quickAdd">Quick-add amount</label><input id="quickAdd" name="quickAdd" type="number" min="0.01" max="1000000000" step="any" required value="${quick(d)}"><label class="check-label"><input id="reminder-enabled" type="checkbox" name="reminder" ${d.reminder?.enabled?'checked':''}> Remind me when work remains</label><div id="reminder-fields" ${!d.reminder?.enabled?'hidden':''}><label for="reminderTime">Reminder around</label><input id="reminderTime" name="reminderTime" type="time" value="${d.reminder?.time||'18:00'}"><p class="help">Cheeky reminders with your challenge name and what’s left today. Only on scheduled days with work remaining. Android may delay delivery to save battery.</p></div></details><details class="options-panel" id="link-options" ${d.link?'open':''}><summary>Link an event or challenge <span>Optional</span></summary><label class="check-label"><input id="link-enabled" name="linkEnabled" type="checkbox" ${d.link?'checked':''}> Connect to a page online</label><div id="link-fields" ${!d.link?'hidden':''}><label for="link-kind">Page type</label><select id="link-kind" name="linkKind">${Object.entries(linkKinds).map(([key,label])=>`<option value="${key}" ${(d.link?.kind||'online')===key?'selected':''}>${label}</option>`).join('')}</select><label for="link-name">Event or challenge name (optional)</label><input id="link-name" name="linkName" maxlength="80" placeholder="e.g. Community fundraiser" value="${esc(d.link?.label||'')}"><label for="link-url">Page address</label><input id="link-url" name="linkUrl" type="text" inputmode="url" autocapitalize="none" spellcheck="false" maxlength="2048" placeholder="https://…" value="${esc(d.link?.url||'')}"><p class="help">The page opens in your browser. Zelo tracks your progress here; event registration and fundraising stay on the linked site.</p></div></details><div id="goal-preview" class="help" aria-live="polite"></div><p class="error" id="form-error" role="alert"></p><button class="primary full" type="submit">${c?'Save changes':'Create challenge'}</button></form>`);
 const form=$('#challenge-form');
 const draft=()=>{const f=new FormData(form),ds=f.getAll('days').map(Number);return {...c,id:c?.id||'preview',name:f.get('name').trim()||'Your challenge',mode:f.get('mode'),goal:Number(f.get('goal')),unit:f.get('unit').trim()||'units',start:f.get('start'),end:f.get('end'),schedule:{days:ds,weekly:f.get('mode')==='daily'?Number(f.get('weekly')):ds.length},capacity:f.get('mode')==='total'&&f.has('capacity')?{weekday:Number(f.get('weekdayLimit')),weekend:Number(f.get('weekendLimit'))}:undefined,link:f.has('linkEnabled')?challengeLink(f.get('linkKind'),f.get('linkName'),f.get('linkUrl')):undefined,quickAdd:Number(f.get('quickAdd')),reminder:{enabled:f.has('reminder'),time:f.get('reminderTime')||'18:00'},logs:c?.logs||[]};};
 const update=()=>{
  $('#form-error').textContent='';$('#link-fields').hidden=!$('#link-enabled').checked;const daily=$('#mode').value==='daily';$('#weekly-wrap').hidden=!daily;$('#capacity-wrap').hidden=daily;$('#capacity-fields').hidden=!$('#capacity-enabled').checked;$('#reminder-fields').hidden=!$('#reminder-enabled').checked;
  const count=form.querySelectorAll('[name="days"]:checked').length;const options=$('#weekly').options;for(const option of options)option.disabled=Number(option.value)>count;if(Number($('#weekly').value)>count&&count)$('#weekly').value=String(count);
  $('label[for="goal"]').textContent=daily?'Target per session':'Total target';$('#mode-help').textContent=daily?'Each target day counts separately. Extra effort cannot replace a missed day.':'Log whenever you can. Zelo adjusts remaining work across your scheduled days.';
  try{const next=validateChallenge(draft()),st=stats(next);$('#goal-preview').className=st.capacityShortfall&&next.capacity?'plan-warning':'help';$('#goal-preview').textContent=st.capacityShortfall&&next.capacity?`${fmt(roundUp(st.capacityShortfall))} ${next.unit} won’t fit within your limits. Extend the end date or increase your limits.`:next.mode==='total'?`${st.remainingDays} scheduled days left · ${fmt(roundUp(st.due))} ${next.unit} remaining today${st.scheduledToday?'':' (rest day)'}.`:`${st.required} target sessions across this challenge.`;}catch(e){$('#goal-preview').textContent='';}
 };
 form.addEventListener('input',update);form.addEventListener('change',update);update();
 form.onsubmit=e=>{e.preventDefault();try{const next=validateChallenge({...draft(),id:c?.id||uid(),name:new FormData(form).get('name').trim()});const st=stats(next);if(next.capacity&&st.capacityShortfall>0)throw Error(`This deadline is ${fmt(roundUp(st.capacityShortfall))} ${next.unit} beyond your limits. Extend the date or increase the limits before saving.`);if(persist(c?challenges.map(x=>x.id===c.id?next:x):[...challenges,next])){if(next.reminder.enabled)window.StrideAndroid?.requestNotifications();close();view='challenges';filter='active';render();toast(c?'Challenge updated.':'Your next chapter starts here.');}}catch(err){$('#form-error').textContent=err.message;$('#form-error').scrollIntoView({block:'nearest'});}};
}
function saveLog(c,amount,date,note='',id=null){const entry={id:id||uid(),amount,date,note};const exists=id&&c.logs.some(l=>l.id===id);const next={...c,logs:exists?c.logs.map(l=>l.id===id?entry:l):[...c.logs,entry]};validateChallenge(next);return persist(challenges.map(x=>x.id===c.id?next:x));}
function quickLog(id){const c=challenges.find(c=>c.id===id);try{if(!c||today()<c.start||today()>c.end)throw Error('This challenge is outside its date range.');const entryId=uid(),amount=quick(c),date=today();if(saveLog(c,amount,date,'Quick add',entryId)){render();toast(`Added ${fmt(amount)} ${c.unit}.`,()=>{const current=challenges.find(x=>x.id===id),entry=current?.logs.find(l=>l.id===entryId);if(!entry||entry.amount!==amount||entry.date!==date||entry.note!=='Quick add'){toast('This entry changed. You can edit it in Activity.');return;}if(persist(challenges.map(x=>x.id===id?{...x,logs:x.logs.filter(l=>l.id!==entryId)}:x))){render();toast('Quick add undone.');}});}}catch(e){toast(e.message);}}
function logForm(id,logId=null){const c=challenges.find(c=>c.id===id);if(!c)return;const l=c.logs.find(l=>l.id===logId);if(c.start>today()){toast('This challenge hasn’t started yet.');return;}const max=c.end<today()?c.end:today();open(`${title(l?'Edit your effort':'Put it on the board.')}<p>${esc(c.name)}</p><form id="log-form"><label for="amount">How many ${esc(c.unit)}?</label><input id="amount" name="amount" type="number" step="any" min="0.01" max="1000000000" inputmode="decimal" required value="${l?.amount||''}" autofocus><div class="quick">${(run(c)?[1,3,5]:[10,25,50]).map(n=>`<button type="button" data-add="${n}">+${n}</button>`).join('')}</div><label for="date">Date</label><input id="date" name="date" type="date" min="${c.start}" max="${max}" value="${l?.date||max}" required><label for="note">A note (optional)</label><textarea id="note" name="note" maxlength="500" rows="2">${esc(l?.note||'')}</textarea><p class="error" id="form-error" role="alert"></p><button class="primary full" type="submit">${l?'Save changes':'Save progress'}</button></form>`);const logDraft=$('#log-form');logDraft.dataset.challengeId=c.id;logDraft.dataset.followsToday=l?'false':'true';const keepChosenDate=()=>{logDraft.dataset.followsToday='false';};$('#date').addEventListener('input',keepChosenDate);$('#date').addEventListener('change',keepChosenDate);$('#log-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{if(saveLog(c,Number(f.get('amount')),f.get('date'),f.get('note').trim(),l?.id)){close();render();toast('Progress saved. That effort counts.');}}catch(err){$('#form-error').textContent=err.message;}};}
function planForm(id){const c=challenges.find(c=>c.id===id);if(!c||c.mode!=='total')return;
 open(`${title('Find a plan that fits.')}<p>See exactly what changes before you save.</p><div class="plan-options"><button class="secondary" id="spread">Keep current deadline</button><button class="secondary" id="extend">${c.capacity?'Find a date within my limits':'Find a date at my original pace'}</button></div><label for="plan-end">Preview deadline</label><input id="plan-end" type="date" min="${[today(),c.start,...c.logs.map(l=>l.date)].sort().at(-1)}" value="${c.end}"><div id="plan-preview" aria-live="polite"></div><p class="error" id="form-error" role="alert"></p><button class="primary full" id="save-plan">Confirm this plan</button>`);
 let preview;const update=()=>{try{preview=catchup(c,$('#plan-end').value);const future=preview.future.filter(p=>p.amount>0);$('#plan-preview').innerHTML=`<div class="plan-preview"><span class="category">LEFT TODAY</span><strong>${fmt(preview.todayRemaining)} <small>${esc(c.unit)}${scheduled({...c,end:preview.end},today())?'':' · rest day'}</small></strong><p>${fmt(preview.remaining)} ${esc(c.unit)} remaining in total · deadline ${dateLabel(preview.end)}.</p>${future.length?`<details class="options-panel" open><summary>Upcoming targets</summary><div class="target-list">${future.slice(0,7).map(p=>`<div><span>${dateLabel(p.date)}</span><b>${fmt(p.amount)} ${esc(c.unit)}</b></div>`).join('')}</div>${future.length>7?`<p class="help">Plus ${future.length-7} later scheduled days. Targets adjust after each day’s actual progress.</p>`:''}</details>`:'<p class="help">No later scheduled days in this plan.</p>'}${preview.shortfall?`<p class="plan-warning">${fmt(roundUp(preview.shortfall))} ${esc(c.unit)} won’t fit within your limits. Choose a later date.</p>`:''}</div>`;$('#form-error').textContent='';$('#save-plan').disabled=preview.shortfall>0;}catch(e){preview=null;$('#form-error').textContent=e.message;$('#save-plan').disabled=true;}};
 $('#plan-end').oninput=update;$('#spread').onclick=()=>{$('#plan-end').value=c.end;update();};$('#extend').onclick=()=>{$('#plan-end').value=suggestedDeadline(c);update();};$('#save-plan').onclick=()=>{if(!preview||preview.shortfall)return;const next={...c,end:preview.end,adjustments:[...(c.adjustments||[]),{date:today(),oldEnd:c.end,end:preview.end,perSession:preview.perSession}]};if(persist(challenges.map(x=>x.id===c.id?next:x))){close();render();toast('Plan saved. Today’s target matches your preview.');}};update();
}
function repeatForm(id){const c=challenges.find(c=>c.id===id),baseStart=c.end>=today()?addDays(c.end,1):today();const monthly=c.start.endsWith('-01')&&c.end===monthEnd(c.start),start=monthly&&!baseStart.endsWith('-01')?addDays(monthEnd(baseStart),1):baseStart;
 open(`${title('Start a fresh chapter.')}<p>Keep your goal and settings. Your old logs stay with the original challenge.</p><label for="repeat-kind">Repeat for</label><select id="repeat-kind"><option value="month" ${monthly?'selected':''}>A calendar month</option><option value="duration" ${!monthly?'selected':''}>The same number of days (${daysBetween(c.start,c.end)})</option></select><label for="repeat-start">New start date</label><input id="repeat-start" type="date" value="${start}"><p class="help" id="repeat-dates"></p>${c.link?`<label class="check-label"><input id="repeat-link" type="checkbox"> Keep the linked page</label><p class="help">${esc(c.link.label||new URL(c.link.url).hostname)} · leave this off if the event is for the old dates.</p>`:''}<p class="help">Reminders start off. You can switch them on in the new challenge.</p><p class="error" id="form-error" role="alert"></p><button class="primary full" id="confirm-repeat">Create repeat</button>`);
 const draft=()=>{const date=$('#repeat-start').value;if($('#repeat-kind').value==='month'&&date&&!date.endsWith('-01'))throw Error('Start on the 1st for a full calendar month, or choose the same number of days.');return validateChallenge({...repeatChallenge(c,date,'preview',$('#repeat-kind').value),link:$('#repeat-link')?.checked?c.link:undefined});};
 const update=()=>{try{const r=draft();$('#repeat-dates').textContent=`${dateRange(r)} · ${daysBetween(r.start,r.end)} days`;$('#form-error').textContent='';$('#confirm-repeat').disabled=false;}catch(e){$('#form-error').textContent=e.message;$('#confirm-repeat').disabled=true;}};
 $('#repeat-kind').onchange=()=>{if($('#repeat-kind').value==='month'&&!$('#repeat-start').value.endsWith('-01'))$('#repeat-start').value=addDays(monthEnd($('#repeat-start').value||today()),1);update();};$('#repeat-start').oninput=update;
 $('#confirm-repeat').onclick=()=>{try{const next={...draft(),id:uid()};if(persist([...challenges,next])){selected=next.id;close();render();toast('Fresh chapter. Same ambition.');}}catch(e){$('#form-error').textContent=e.message;}};update();
}
function activityRows(items){return items.map(l=>`<div class="activity-row"><span class="log-marker">${run(l.challenge)?'↗':'+'}</span><div class="activity-text"><b>${esc(l.challenge.name)}</b><p>${dateLabel(l.date)} ${l.date.slice(0,4)}${l.note?' · '+esc(l.note):''}</p></div><span class="activity-amount">+${fmt(l.amount)} <small>${esc(l.challenge.unit)}</small></span><button class="text-button" data-edit-log="${esc(l.id)}" data-cid="${esc(l.challenge.id)}" aria-label="Edit log">Edit</button><button class="text-button danger" data-delete-log="${esc(l.id)}" data-cid="${esc(l.challenge.id)}" aria-label="Delete log">×</button></div>`).join('')||'<div class="quiet-card"><h3>Your effort belongs here.</h3><p>Add your first log to start your story.</p></div>';}
function graph(c){const points=chartPoints(c),s=stats(c);let values=points;if(points.length>180){const stride=Math.ceil(points.length/180);values=points.filter((p,i)=>i%stride===0||i===points.length-1);}const max=Math.max(1,s.target,...points.map(p=>Math.max(p.planned,p.actual||0)));const xy=(p,v)=>`${30+(dayNumber(p.date)-dayNumber(c.start))/Math.max(1,daysBetween(c.start,c.end)-1)*540},${170-v/max*145}`;const actual=values.filter(p=>p.actual!==null);return `<div class="progress-chart"><div class="chart-legend"><span><i></i>Actual effort</span><span><i class="planned"></i>Planned effort${c.mode==='daily'&&c.schedule?.weekly<trainingDays(c).length?' (eligible days)':''}</span></div><svg viewBox="0 0 600 205" role="img" aria-label="Cumulative actual versus planned effort, in ${esc(c.unit)}"><path d="M30 25V170H570" fill="none" stroke="var(--line)"/><path d="M30 97H570 M30 25H570" stroke="var(--line)" stroke-dasharray="3 6"/><polyline points="${points.length===1?'30,170 ':''}${values.map(p=>xy(p,p.planned)).join(' ')}" fill="none" stroke="#9894b6" stroke-width="2" stroke-dasharray="5 6"/><polyline points="${actual.map(p=>xy(p,p.actual)).join(' ')}" fill="none" stroke="#A78BFA" stroke-width="3" stroke-linejoin="round"/>${actual.length?`<circle cx="${xy(actual.at(-1),actual.at(-1).actual).split(',')[0]}" cy="${xy(actual.at(-1),actual.at(-1).actual).split(',')[1]}" r="4" fill="#FF2D87"/>`:''}<text x="30" y="196">${dateLabel(c.start)}</text><text x="570" y="196" text-anchor="end">${dateLabel(c.end)}</text></svg></div>`;}
function linkedPage(c){if(!c.link)return '';const url=new URL(c.link.url);return `<aside class="linked-page" aria-label="Linked event or challenge"><div><span class="category">${esc(linkKinds[c.link.kind])}</span><h3>${esc(c.link.label||url.hostname)}</h3><p>${esc(url.hostname)}</p></div><a class="secondary" href="${esc(c.link.url)}" target="_blank" rel="noopener noreferrer" data-external="${esc(c.link.url)}">Open page <span aria-hidden="true">↗</span></a></aside>`;}
function detail(){const c=challenges.find(x=>x.id===selected);if(!c){selected=null;return render();}const s=stats(c),daily=c.mode==='daily';const cal=[];const start=Math.max(dayNumber(c.start),Math.min(dayNumber(today()),dayNumber(c.end))-27);for(let n=start;n<=Math.min(dayNumber(c.end),start+34);n++){const d=fromDay(n),value=s.byDay[d]||0;cal.push(`<div class="day ${!scheduled(c,d)?'rest':value+1e-9>=(daily?c.goal:s.baseline)?'hit':value?'partial':''} ${d>today()?'future':''}" title="${d}: ${fmt(value)} ${esc(c.unit)}${!scheduled(c,d)?' (rest day)':''}">${dateLabel(d)}</div>`);}
 const family=challenges.filter(x=>(x.seriesId||x.id)===(c.seriesId||c.id)&&x.unit===c.unit&&x.mode===c.mode);const personalBest=Math.max(0,...family.flatMap(x=>Object.values(stats(x).byDay)));
 main.innerHTML=`<button class="back" data-action="back">← Your challenges</button><div class="detail-head"><div><div class="eyebrow">${daily?'STRICT SESSIONS':'FLEXIBLE TOTAL'} / ${s.status}</div><h1>${esc(c.name)}</h1><p>${dateRange(c)} · ${scheduleLabel(c)}</p></div><button class="secondary" data-edit="${esc(c.id)}">Edit</button></div>${linkedPage(c)}<div class="detail-layout"><section class="card feature-card"><div class="category">${daily?'SESSIONS ACHIEVED':'YOUR PROGRESS'}</div><div class="progress-number"><strong>${fmt(daily?s.hitDays:s.total)} <small>/ ${fmt(daily?s.required:s.target)} ${daily?'sessions':esc(c.unit)}</small></strong><span>${Math.floor(s.progress*100)}%</span></div><div class="track"><i style="width:${s.progress*100}%"></i></div>${graph(c)}<p class="forecast">${s.completed?'✓ Goal complete. You made it.':daily?`${s.hitDays} of ${s.required} required sessions met · ${s.missed} missed. Extra work doesn’t replace missed sessions.`:s.forecast?`At your current pace, estimated finish: <b>${dateLabel(s.forecast)} ${s.forecast.slice(0,4)}</b>.`:'Log your first effort to see a finish forecast.'}</p><p class="help">${daily?'The chart shows total effort. Target days are counted separately.':'Forecast uses average effort per elapsed scheduled day, including today. It is an estimate, not a promised finish date.'}</p></section><div class="detail-grid"><div class="stat-box"><small>Remaining today</small><strong>${fmt(roundUp(s.due))}</strong><small>${esc(c.unit)}${!s.scheduledToday?' · rest day':s.weekDone?' · weekly quota met':''}</small></div><div class="stat-box"><small>${daily?'Missed sessions':'Still remaining'}</small><strong>${daily?s.missed:fmt(s.remaining)}</strong><small>${daily?'Strict targets stay honest':esc(c.unit)+(c.end<today()?' · deadline passed':' · total goal')}</small></div><div class="stat-box"><small>Current streak</small><strong>${s.streak}</strong><small>Scheduled days meeting original pace</small></div><div class="stat-box"><small>Daily average</small><strong>${fmt(s.average)}</strong><small>${esc(c.unit)} / elapsed scheduled day</small></div></div></div>${s.capacityShortfall>0&&c.capacity&&c.end>=today()?'<p class="plan-warning">This deadline no longer fits your limits. Adjust the plan to choose a later date.</p>':''}<div class="detail-actions"><button class="primary" data-log="${esc(c.id)}">＋ Log progress</button>${!daily?`<button class="secondary" data-plan="${esc(c.id)}">Adjust plan ↗</button>`:''}<button class="secondary" data-repeat="${esc(c.id)}">Repeat challenge</button></div><div class="toolbar"><h2>Your consistency</h2><span>${cal.length} days shown</span></div><p class="help">Violet = target met · outlined = rest day. ${daily?'Weekly quotas can be met on any selected scheduled days.':'Daily markers use your original pace.'}</p><div class="calendar">${cal.join('')}</div><div class="toolbar"><h2>Your personal benchmark</h2><span>${family.length} ${family.length===1?'chapter':'chapters'}</span></div><div class="comparison"><div><span class="category">BEST SINGLE DAY</span><strong>${fmt(personalBest)} <small>${esc(c.unit)}</small></strong></div><div><span class="category">THIS CHAPTER</span><strong>${fmt(s.total)} <small>${esc(c.unit)} so far</small></strong></div></div>${family.length>1?`<div class="table-wrap"><table><thead><tr><th>Chapter</th><th>Total ${esc(c.unit)}</th><th>Progress</th><th>Active days</th></tr></thead><tbody>${family.map(x=>`<tr><td><button class="text-button" data-detail="${esc(x.id)}">${dateRange(x)}</button></td><td>${fmt(stats(x).total)}</td><td>${Math.floor(stats(x).progress*100)}%</td><td>${new Set(x.logs.map(l=>l.date)).size}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="toolbar"><h2>Activity log</h2><span>${c.logs.length} entries</span></div>${activityRows(logs().filter(l=>l.challenge.id===c.id))}${c.adjustments?.length?`<div class="toolbar"><h2>Plan history</h2></div>${c.adjustments.map(a=>`<p class="help">${dateLabel(a.date)} · ${dateLabel(a.oldEnd)} → ${dateLabel(a.end)} · ${fmt(a.perSession)} ${esc(c.unit)} / scheduled day at revision</p>`).join('')}`:''}<div class="brand-footer"><button class="text-button danger" data-delete-challenge="${esc(c.id)}">Delete challenge</button><b>by ecletra</b></div>`;
}
function activity(){main.innerHTML=heading('THE EFFORT BEHIND THE PROGRESS','Your work,<br><em>recorded.</em>','Every small action has a place here.',false)+`<div class="toolbar"><h2>Activity log</h2><select id="activity-filter" aria-label="Filter activity"><option value="">All challenges</option>${challenges.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div id="activity-list">${activityRows(logs())}</div>`;$('#activity-filter').onchange=e=>{$('#activity-list').innerHTML=activityRows(logs().filter(l=>!e.target.value||l.challenge.id===e.target.value));};}
function insights(){const entries=logs(),activeDays=new Set(entries.map(l=>l.date));const week=Array.from({length:7},(_,i)=>{const d=addDays(today(),i-6);return {date:d,count:entries.filter(l=>l.date===d).length};});const max=Math.max(1,...week.map(d=>d.count));main.innerHTML=heading('TAKE THE LONG VIEW','Effort leaves<br><em>a trail.</em>','Your goals, viewed over time.',false)+weeklyReviews()+`<div class="insight-grid"><div class="stat-box"><small>Total entries</small><strong>${entries.length}</strong><small>Efforts worth counting</small></div><div class="stat-box"><small>Active days</small><strong>${activeDays.size}</strong><small>Days you showed up</small></div><div class="stat-box"><small>Completed challenges</small><strong>${challenges.filter(c=>stats(c).completed).length}</strong><small>Chapters finished</small></div></div><section class="card"><div class="section-heading"><h2>Recent activity</h2><span>Last 7 days · number of logs</span></div><div class="bar-chart">${week.map(d=>`<div class="bar-group"><small>${d.count}</small><div class="bar" style="height:${d.count/max*110}px"></div><small>${weekdays[weekday(d.date)]}</small></div>`).join('')}</div></section><div class="toolbar"><h2>Challenge breakdown</h2></div><div class="cards">${challenges.map(card).join('')||empty()}</div>`;}
function settings(){const native=!!window.StrideAndroid;open(`${title('Settings')}<div class="about-brand"><span class="product-mark">Z</span><div><strong>Zelo · by ecletra</strong><p>Turn effort into progress.</p></div></div><h3>Keep your progress safe</h3><div id="auto-backup-status"></div>${native?'<button class="primary full" data-action="backup-setup">Set up automatic backup</button>':'<p class="help">Automatic Drive/file backups are available in the Android app.</p>'}<details class="options-panel"><summary>Manual backup & restore</summary><button class="secondary full" data-action="export">Export a backup</button><button class="secondary full" data-action="import">Restore from a file</button><p class="help">Restoring replaces your current challenges. You’ll review the file before confirming.</p></details><h3>Make logging easier</h3>${native?'<button class="secondary full" data-action="widget">Add home-screen widget</button><button class="secondary full" data-action="notifications">Notification settings</button>':'<p class="help">Widgets and reminders are available on Android.</p>'}<p class="help">Set reminders inside a challenge’s Schedule & reminders. Delivery may be delayed by battery settings.</p><details class="options-panel"><summary>About Zelo</summary><p>Zelo is inspired by Zelos, the Greek spirit of zeal and emulation. Your benchmark is your own previous chapter.</p><p class="help">Independent software. Cleverly built. No health-data integrations.</p></details><div class="brand-footer"><span>Zelo 2.3.1</span><b>by ecletra</b></div>`);updateBackupStatus();}
function updateBackupStatus(){const box=$('#auto-backup-status');if(!box||!window.StrideAndroid?.backupStatus)return;try{const b=JSON.parse(window.StrideAndroid.backupStatus());box.innerHTML=!b.enabled?'<p class="help">Automatic backups are off. Choose Google Drive or another location in Android’s file picker.</p>':`<div class="backup-status"><strong>${b.reconnect?'Choose your backup file again':b.error?'Backup needs attention':b.pending||b.hasChanges?'Changes waiting to back up':'Backup file is up to date'}</strong><p>${esc(b.name||'Zelo backup')}</p><p class="help">${b.lastSaved?'Last saved: '+new Date(b.lastSaved).toLocaleString():'First backup hasn’t finished yet.'}</p>${b.error?`<p class="help">${esc(b.error)}</p>`:''}<div class="mission-actions"><button class="secondary" data-action="backup-now">Back up now</button><button class="text-button" data-action="backup-setup">Change file</button><button class="text-button" data-action="backup-stop">Turn off</button></div></div>`;}catch(e){box.textContent='Backup status is unavailable. Your progress is still on this device.';}}
function backupSetup(){open(`${title('Automatic backup')}<p>Keep up to 10 recent versions in one backup file.</p><ol class="setup-steps"><li>Tap Choose backup file.</li><li>In Android’s file picker, choose <b>Google Drive</b> (or another location).</li><li>Save the file. Zelo updates it after your progress changes.</li></ol><p class="help">Drive handles cloud upload. If your phone is offline, it may finish syncing later. The last-saved status means the backup file was updated.</p><button class="primary full" data-action="backup-connect">Choose backup file</button><button class="secondary full" data-action="settings">Back to settings</button>`);}

function weeklyReviews(){
 const current=reviewPeriod==='current',all=challenges.map(c=>({c,r:weeklyReview(c)}));
 const rows=all.filter(({r})=>current?r.nextSessions||r.currentTotal:r.expected||r.total);
 const range=all[0]?.r;
 return `<section class="weekly-review"><div class="section-heading"><h2>Your weekly review</h2><div class="tabs" role="group" aria-label="Review period"><button data-review="current" class="${current?'selected':''}">This week</button><button data-review="last" class="${!current?'selected':''}">Last week</button></div></div><p class="review-period">${range?`${dateLabel(current?range.nextStart:range.start)} – ${dateLabel(current?range.nextEnd:range.end)} · Monday–Sunday`:'Monday–Sunday'}${current?' · In progress':''}</p>${!rows.length?`<p>${current?'No challenges are scheduled this week yet.':'No scheduled goals or activity last week.'}</p>`:rows.map(({c,r})=>{
  const amount=current?r.currentTotal:r.total,days=current?r.currentActiveDays:r.activeDays;
  let summary,next='';
  if(c.mode==='daily'){
   const hits=current?r.nextCompleted:r.completed,required=current?r.nextSessions:r.expected,missed=current?r.nextMissed:r.missed;
   summary=required?`${hits} of ${required} target ${required===1?'day':'days'} met${missed?` · ${missed} missed`:''}.`:'No targets scheduled for this week.';
   if(current&&required)next=r.nextAvailableSessions?`${r.nextAvailableSessions} more target ${r.nextAvailableSessions===1?'day can':'days can'} be completed this week. ${fmt(r.todayRemaining)} ${esc(c.unit)} left today.`:r.nextRemainingSessions?'No eligible days remain to make up those missed targets.':'This week’s target is met.';
  }else if(current){
   summary=stats(c).completed?'Overall goal complete.':`${fmt(r.nextRemaining)} ${esc(c.unit)} remaining in this week’s plan.`;
   next=r.ended?'This challenge has ended.':`${r.nextTrainingDays} scheduled ${r.nextTrainingDays===1?'day':'days'} left this week · ${fmt(r.todayRemaining)} ${esc(c.unit)} left today.`;
  }else{
   summary=r.completedAtEnd?'Overall goal was complete by the end of this week.':Math.abs(r.paceDifference)<0.005?'On pace at the end of this week.':`${fmt(Math.abs(r.paceDifference))} ${esc(c.unit)} ${r.paceDifference>0?'ahead of':'behind'} the overall plan at week end.`;
   next='Earlier progress counts towards your overall pace.';
  }
  return `<article class="review-row"><button class="card-title" data-detail="${esc(c.id)}"><h3>${esc(c.name)}</h3></button><p>${fmt(amount)} ${esc(c.unit)} logged on ${days} ${days===1?'day':'days'}.</p><p><strong>${summary}</strong></p>${next?`<p class="help">${next}</p>`:''}</article>`;
 }).join('')}</section>`;
}
function exportBackup(){const json=JSON.stringify({version:2,challenges},null,2);if(new Blob([json]).size>5e6){toast('Backup exceeds the 5 MB import limit.');return;}if(window.StrideAndroid){window.StrideAndroid.exportData(json);return;}const url=URL.createObjectURL(new Blob([json],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='zelo-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded.');}

function confirmRestore(incoming){open(`${title('Restore your progress?')}<p>This file contains <strong>${incoming.length} challenges</strong> and <strong>${incoming.reduce((n,c)=>n+c.logs.length,0)} logs</strong>.</p><p>It will replace your current ${challenges.length} challenges. Export them first if you want to keep them.</p><button class="primary full" id="confirm-restore">Replace and restore</button><button class="secondary full" data-action="close">Cancel</button>`);$('#confirm-restore').onclick=()=>{if(persist(incoming)){loadError=false;selected=null;close();render();toast('Your progress is restored.');}};}
window.restoreBackup=text=>{try{const file=JSON.parse(text);if(file.format!=='zelo-backup-history'){confirmRestore(parseBackup(text));return;}if(file.version!==1||!Array.isArray(file.snapshots)||!file.snapshots.length||file.snapshots.length>10)throw Error('This backup history is not supported.');const versions=file.snapshots.flatMap((v,i)=>{try{const challenges=parseBackup(JSON.stringify(v.data));if(!Number.isFinite(Date.parse(v.savedAt)))return [];return [{...v,challenges,index:i}];}catch{return [];}});if(!versions.length)throw Error('No readable backup versions found.');open(`${title('Choose a backup version')}<p>Pick the progress you want to restore. Your current challenges will be replaced.</p><label for="backup-version">Saved version</label><select id="backup-version">${versions.map((v,i)=>`<option value="${i}" ${i===versions.length-1?'selected':''}>${i===versions.length-1?'Most recent · ':''}${esc(new Date(v.savedAt).toLocaleString())} · ${v.challenges.length} challenges</option>`).join('')}</select><p id="version-summary" class="help"></p><button class="primary full" id="review-version">Review this version</button><button class="secondary full" data-action="close">Cancel</button>`);const summary=()=>{const v=versions[Number($('#backup-version').value)];$('#version-summary').textContent=`${v.challenges.reduce((n,c)=>n+c.logs.length,0)} logs in this version. Nothing changes until you confirm on the next screen.`;};$('#backup-version').onchange=summary;$('#review-version').onclick=()=>confirmRestore(versions[Number($('#backup-version').value)].challenges);summary();}catch(e){toast('Could not restore: '+e.message);}};
window.backupConnected=()=>{settings();toast('Backup file selected. Your first backup is queued.');};
window.backupConnectionFailed=()=>{settings();toast('That location did not allow ongoing access. Choose a different backup file.');};
window.backupSaved=()=>toast('Backup saved.');window.backupFailed=()=>toast('Could not read or save the backup. Try another file.');window.handleBack=()=>{if(modal.open){close();return true;}if(selected){selected=null;view='challenges';render();return true;}if(view!=='today'){go('today');return true;}return false;};
$('#import-file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>5e6)toast('Choose a backup smaller than 5 MB.');else window.restoreBackup(await f.text());}e.target.value='';};
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand,a[data-external]');if(!b)return;if(b.dataset.external){if(window.StrideAndroid?.openExternalLink){e.preventDefault();window.StrideAndroid.openExternalLink(b.dataset.external);}return;}const d=b.dataset;if(d.review){reviewPeriod=d.review;render();return;}if(b.matches('.brand')){e.preventDefault();go('today');}if(d.nav)go(d.nav);if(d.filter){filter=d.filter;render();}if(d.detail){selected=d.detail;view='challenges';render();window.scrollTo(0,0);}if(d.log)logForm(d.log);if(d.quick)quickLog(d.quick);if(d.edit)challengeForm(d.edit);if(d.plan)planForm(d.plan);if(d.repeat)repeatForm(d.repeat);if(d.template)challengeForm(null,d.template);if(d.editLog)logForm(d.cid,d.editLog);if(d.add)$('#amount').value=Math.round(((Number($('#amount').value)||0)+Number(d.add))*100)/100;
 if(d.deleteLog){const c=challenges.find(c=>c.id===d.cid),l=c.logs.find(l=>l.id===d.deleteLog);open(`${title('Delete this entry?')}<p>${fmt(l.amount)} ${esc(c.unit)} on ${dateLabel(l.date)} will be removed.</p><button class="primary full" id="confirm-delete">Delete entry</button><button class="secondary full" data-action="close">Keep entry</button>`);$('#confirm-delete').onclick=()=>{if(persist(challenges.map(x=>x.id===c.id?{...x,logs:x.logs.filter(y=>y.id!==l.id)}:x))){close();render();toast('Entry deleted.');}};}
 if(d.deleteChallenge){const c=challenges.find(c=>c.id===d.deleteChallenge);open(`${title('Delete this challenge?')}<p>${esc(c.name)} and all ${c.logs.length} entries will be removed.</p><button class="primary full" id="confirm-delete">Delete challenge</button><button class="secondary full" data-action="close">Keep challenge</button>`);$('#confirm-delete').onclick=()=>{if(persist(challenges.filter(x=>x.id!==c.id))){selected=null;close();render();toast('Challenge deleted.');}};}
 if(d.action==='settings')settings();if(d.action==='backup-setup')backupSetup();if(d.action==='backup-connect')window.StrideAndroid?.connectBackup();if(d.action==='backup-now'){window.StrideAndroid?.backupNow();updateBackupStatus();toast('Backup requested. You can keep using Zelo.');}if(d.action==='backup-stop'){open(`${title('Turn off automatic backups?')}<p>Your existing backup file stays where it is. New changes will only be saved on this device until you set up backups again.</p><button class="primary full" id="stop-backup-confirm">Turn off automatic backups</button><button class="secondary full" data-action="settings">Keep backups on</button>`);$('#stop-backup-confirm').onclick=()=>{window.StrideAndroid?.stopBackups();settings();};}
 if(d.action==='new')challengeForm();if(d.action==='close')close();if(d.action==='back')go('challenges');if(d.action==='export')exportBackup();if(d.action==='import'){if(window.StrideAndroid)window.StrideAndroid.importData();else $('#import-file').click();}if(d.action==='widget')window.StrideAndroid?.pinWidget();if(d.action==='notifications')window.StrideAndroid?.notificationSettings();
});
setInterval(()=>{if(modal.open&&$('#auto-backup-status'))updateBackupStatus();},2000);
$('#settings').onclick=settings;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
setInterval(()=>refreshCurrentDay(),30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshCurrentDay({force:true,readNative:true});});
window.addEventListener('focus',()=>refreshCurrentDay({force:true,readNative:true}));
window.addEventListener('pageshow',()=>refreshCurrentDay({force:true,readNative:true}));
// Recheck before handling an action: a sleeping WebView may not have run its timers yet.
document.addEventListener('click',()=>refreshCurrentDay(),true);
document.addEventListener('submit',()=>refreshCurrentDay(),true);
scheduleDayRefresh();
render();if(loadError)open(`${title('Saved data needs attention')}<p>Your saved progress couldn’t be read. It has not been overwritten. Restore a backup before adding new challenges.</p><button class="primary full" data-action="import">Restore backup</button>`);
